mapper.select:
/* userProfileMapper.getUserProfile */
SELECT *
FROM   T_USER_INFO
WHERE  1 = 1
AND   USER_ID = #{userId}

mapper.insert:
/* userProfileMapper.insertUserProfile */
INSERT INTO T_USER_INFO (USER_ID, PASSWORD, NAME, EMAIL, PHONE_NUMBER, GENDER, BIRTH, CREATE_TIME)
VALUES (#{userId}, #{password}, #{name}, #{email}, #{phoneNumber}, #{gender}, #{birth}, NOW())

mapper.update:
/* userProfileMapper.updateUserProfile */
UPDATE T_USER_INFO
SET    UPDATE_TIME = NOW()

,       PASSWORD = #{password}


,       NAME = #{name}


,       EMAIL = #{email}


,       ADDRESS = #{address}


,       DETAIL_ADDRESS = #{detailAddress}


,       CERTI_YN = #{certiYn}


,       PHONE_NUMBER = #{phoneNumber}

WHERE  USER_ID = #{userId}

mapper.delete:
/* userProfileMapper.deleteUserProfile */
DELETE FROM T_USER_INFO
WHERE  USER_ID = #{userId}
AND    PASSWORD = #{password}

mapper.select:
/* userProfileMapper.findByIdAndPassword */
SELECT *
FROM   T_USER_INFO
WHERE  1 = 1
AND    USER_ID = #{userId}
AND    PASSWORD = #{password}

/* userProfileMapper.idCheck */
SELECT COUNT(USER_ID)
FROM   T_USER_INFO
